begin;
-- Existing identities and unfinished V1 sessions are never recalculated.
alter function public.kaidra_awakening_score(jsonb,jsonb) rename to kaidra_awakening_score_v1;
revoke all on function public.kaidra_awakening_score_v1(jsonb,jsonb) from public,anon,authenticated;
create function public.kaidra_awakening_score(questions jsonb,answers jsonb) returns jsonb language plpgsql immutable set search_path='' as $$
declare traits integer[]:=array[0,0,0,0,0,0,0,0];squares integer[]:=array[0,0,0,0,0,0,0,0];q jsonb;o jsonb;i integer;begin
 if jsonb_array_length(questions->0->'options'->0->'weights')=5 then return public.kaidra_awakening_score_v1(questions,answers);end if;
 for q in select value from jsonb_array_elements(questions) loop select value into o from jsonb_array_elements(q->'options') where value->>'id'=answers->>(q->>'id');if o is not null then for i in 1..8 loop traits[i]:=traits[i]+(o->'weights'->>(i-1))::integer;squares[i]:=squares[i]+((o->'weights'->>(i-1))::integer)^2;end loop;end if;end loop;
 return (select jsonb_agg(jsonb_build_object('class_id',id,'score',score,'secondary',secondary,'dominant',dominant) order by score desc,secondary desc,dominant desc,id) from(values
 ('warrior',5*traits[1]+1*traits[3]+2*traits[4]+1*traits[8],5*squares[1]+1*squares[3]+2*squares[4]+1*squares[8],traits[1]),
 ('wizard',5*traits[2]+1*traits[3]+1*traits[4]+2*traits[7],5*squares[2]+1*squares[3]+1*squares[4]+2*squares[7],traits[2]),
 ('ninja',1*traits[2]+5*traits[3]+2*traits[5]+1*traits[7],1*squares[2]+5*squares[3]+2*squares[5]+1*squares[7],traits[3]),
 ('guardian',1*traits[1]+2*traits[2]+5*traits[4]+1*traits[6],1*squares[1]+2*squares[2]+5*squares[4]+1*squares[6],traits[4]),
 ('rogue',2*traits[2]+1*traits[3]+5*traits[5]+1*traits[8],2*squares[2]+1*squares[3]+5*squares[5]+1*squares[8],traits[5]),
 ('healer',1*traits[2]+1*traits[3]+2*traits[4]+5*traits[6],1*squares[2]+1*squares[3]+2*squares[4]+5*squares[6],traits[6]),
 ('ranger',2*traits[2]+1*traits[3]+5*traits[7]+1*traits[8],2*squares[2]+1*squares[3]+5*squares[7]+1*squares[8],traits[7]),
 ('berserker',2*traits[1]+1*traits[3]+2*traits[5]+5*traits[8],2*squares[1]+1*squares[3]+2*squares[5]+5*squares[8],traits[8])) scores(id,score,secondary,dominant));
end $$;
revoke all on function public.kaidra_awakening_score(jsonb,jsonb) from public,anon,authenticated;
insert into public.awakening_questions(version,id,category,prompt,options,pair) select version,id,category,prompt,options,pair from jsonb_to_recordset($pool$[{"version":2,"id":"v2-pattern","prompt":"You are falling behind, but you notice a repeating pattern. What comes naturally?","category":"combat","options":[{"id":"34544f2d41d0","text":"Test the pattern once more before building a reliable response.","weights":[1,4,2,3,2,1,2,1]},{"id":"d512e6cd36f5","text":"Change your rhythm immediately and see how they adjust.","weights":[2,2,4,1,2,1,1,1]},{"id":"3f5979ac1d30","text":"Act as if you missed it and encourage them to overcommit.","weights":[1,3,3,1,4,1,1,1]},{"id":"5279cfcd4db8","text":"Give both sides breathing room and help the quieter person recover confidence.","weights":[0,2,1,3,1,4,1,0]},{"id":"d04230f88999","text":"Watch one small detail closely and act when it becomes reliable.","weights":[1,3,2,1,1,0,4,0]},{"id":"2d0bc5d0e033","text":"Accept a personal cost to force a decisive change in momentum.","weights":[3,1,2,1,2,0,1,4]}],"pair":null},{"version":2,"id":"v2-pressure","prompt":"Someone keeps forcing you to react. How do you regain control?","category":"combat","options":[{"id":"fc4f1f2ecada","text":"Commit to one decisive push instead of retreating again.","weights":[4,1,3,3,1,1,1,2]},{"id":"fd0049958770","text":"Change distance and timing so the same approach stops working.","weights":[2,3,4,1,2,1,1,1]},{"id":"492287063f1f","text":"Hold a dependable position and wait for the pressure to weaken.","weights":[2,2,2,4,2,2,1,1]},{"id":"0a249befc752","text":"Check who is struggling most and help them regain a stable footing.","weights":[0,2,1,3,1,4,1,0]},{"id":"7f1e4efa2bf0","text":"Set a small test that turns uncertainty into a clear signal.","weights":[1,3,2,1,1,0,4,0]},{"id":"6bf6eaf05683","text":"Use the pressure as a reason to commit harder, while recognizing the cost.","weights":[3,1,2,1,2,0,1,4]}],"pair":null},{"version":2,"id":"v2-opening","prompt":"An opening appears, but you cannot see everything behind it. What do you do?","category":"combat","options":[{"id":"dc5fd556f373","text":"Take it decisively and remain ready to withstand the response.","weights":[4,1,2,3,2,1,1,2]},{"id":"336497c9d4d0","text":"Check what created the opening before committing.","weights":[2,4,2,2,2,1,2,1]},{"id":"b4fac3b51aee","text":"Keep your safe position until the opening becomes dependable.","weights":[2,3,1,4,2,2,1,1]},{"id":"a21a657e3641","text":"Make the opening seem less interesting, then use it unexpectedly.","weights":[2,3,2,1,4,1,1,1]},{"id":"4e8b999adc20","text":"Prepare one precise response instead of spreading effort everywhere.","weights":[1,3,2,1,1,0,4,0]},{"id":"133e8c35b483","text":"Take a demanding route and accept the consequences of committing to it.","weights":[3,1,2,1,2,0,1,4]}],"pair":null},{"version":2,"id":"v2-resources","prompt":"You have enough energy for only a few more decisive exchanges. What changes?","category":"combat","options":[{"id":"8d9dac8a3595","text":"Choose one clear commitment and make it count.","weights":[4,2,2,3,1,1,1,2]},{"id":"5337967c6ad6","text":"Spend only on actions that support a connected plan.","weights":[1,4,2,2,2,1,2,1]},{"id":"cf3ebb04f8ff","text":"Use smaller actions and adjust as new information arrives.","weights":[2,3,4,1,2,1,1,1]},{"id":"c06831a06b40","text":"Make the other person spend first, even if the bait is risky.","weights":[1,4,2,1,4,1,1,1]},{"id":"b86b67ecf8b3","text":"Help the person affected most recover before pushing the next step.","weights":[0,2,1,3,1,4,1,0]},{"id":"ef78a7386c17","text":"Push for a decisive step even if it leaves less room for recovery.","weights":[3,1,2,1,2,0,1,4]}],"pair":null},{"version":2,"id":"v2-setback","prompt":"Your best approach just failed. What is your next move?","category":"combat","options":[{"id":"16ab10f10285","text":"Regroup and try again with a stronger commitment.","weights":[4,2,2,3,1,1,1,2]},{"id":"ecc57168fab3","text":"Work out which assumption failed before changing the plan.","weights":[1,4,2,3,2,1,2,1]},{"id":"6d81f78a0a30","text":"Switch approaches quickly instead of defending the old one.","weights":[2,3,4,1,2,1,1,1]},{"id":"8ce63a541491","text":"Stabilize first so the setback cannot become a collapse.","weights":[2,2,1,4,2,2,1,1]},{"id":"eac1d5a6919b","text":"Rebuild trust and confidence so a setback does not spread.","weights":[0,2,1,3,1,4,1,0]},{"id":"1798691dce30","text":"Keep enough distance to observe, then commit to a clear opening.","weights":[1,3,2,1,1,0,4,0]}],"pair":null},{"version":2,"id":"v2-underestimated","prompt":"An opponent treats you as if you cannot threaten them. How do you respond?","category":"combat","options":[{"id":"b16953d37c2e","text":"Use the time they give you to assemble a stronger position.","weights":[1,4,3,2,2,1,2,1]},{"id":"d2776289e846","text":"Change pace before they can settle into an easy rhythm.","weights":[2,2,4,2,2,1,1,1]},{"id":"76310c96067b","text":"Stay disciplined and let their carelessness become the opening.","weights":[3,2,1,4,2,2,1,1]},{"id":"1376932cd614","text":"Keep the impression alive until it can be used against them.","weights":[1,4,2,1,4,1,1,1]},{"id":"a2cc3ecf7f82","text":"Look for a narrow, dependable opportunity that others are overlooking.","weights":[1,3,2,1,1,0,4,0]},{"id":"0f04fd37d663","text":"Trade some safety for an immediate chance to change the situation.","weights":[3,1,2,1,2,0,1,4]}],"pair":null},{"version":2,"id":"v2-uncertainty","prompt":"You meet an unfamiliar opponent. What do you try to learn first?","category":"combat","options":[{"id":"795a5fe3e409","text":"How they respond when a clear boundary is pushed.","weights":[4,2,2,3,1,1,1,2]},{"id":"b1a8d34fb133","text":"How quickly they adjust to changing circumstances.","weights":[2,2,4,1,2,1,1,1]},{"id":"3c87e85e8451","text":"What they do when their first attempt meets resistance.","weights":[2,3,1,4,2,2,1,1]},{"id":"af07f5348680","text":"Which expectations they rely on without questioning them.","weights":[1,3,3,1,4,1,1,1]},{"id":"b9ed7277fd8a","text":"Give both sides breathing room and help the quieter person recover confidence.","weights":[0,2,1,3,1,4,1,0]},{"id":"d7a4463a0f3c","text":"Accept a personal cost to force a decisive change in momentum.","weights":[3,1,2,1,2,0,1,4]}],"pair":null},{"version":2,"id":"v2-momentum","prompt":"You have momentum, but a reckless move could throw it away. What do you do?","category":"combat","options":[{"id":"f18916ccd20d","text":"Keep pressure consistent rather than giving up the initiative.","weights":[4,1,3,3,1,1,1,2]},{"id":"30fb7eb75360","text":"Use the advantage to set up the next two exchanges.","weights":[1,4,2,3,2,1,2,1]},{"id":"a55713e47cad","text":"Consolidate the advantage and make them take the next risk.","weights":[3,2,1,4,2,2,1,1]},{"id":"1e0209b251ad","text":"Offer them a tempting route back and prepare for their response.","weights":[2,3,2,1,4,1,1,1]},{"id":"fc2f44340df1","text":"Check who is struggling most and help them regain a stable footing.","weights":[0,2,1,3,1,4,1,0]},{"id":"13f5f2b01333","text":"Set a small test that turns uncertainty into a clear signal.","weights":[1,3,2,1,1,0,4,0]}],"pair":null},{"version":2,"id":"v2-commitment","prompt":"A tense exchange has reached a standstill. How do you break it?","category":"combat","options":[{"id":"18653afaf71f","text":"Change the conditions that made the standstill possible.","weights":[1,4,2,3,2,1,2,1]},{"id":"5be837dd4009","text":"Try a different rhythm rather than waiting for certainty.","weights":[2,3,4,1,2,1,1,1]},{"id":"22dd59609ef5","text":"Show an intention that conceals the move you actually want.","weights":[2,3,2,1,4,1,1,1]},{"id":"818890f8378e","text":"Spend some of your own margin to keep the whole group moving.","weights":[0,2,1,3,1,4,1,0]},{"id":"e4e3f1b3bc31","text":"Prepare one precise response instead of spreading effort everywhere.","weights":[1,3,2,1,1,0,4,0]},{"id":"b2073df9a0a5","text":"Take a demanding route and accept the consequences of committing to it.","weights":[3,1,2,1,2,0,1,4]}],"pair":null},{"version":2,"id":"v2-recovery","prompt":"After a difficult exchange, both sides need to recover. What matters most?","category":"combat","options":[{"id":"4b472d479aab","text":"Recover enough to keep applying dependable pressure.","weights":[4,1,2,3,1,1,1,2]},{"id":"0171d954de51","text":"Stay ready to change direction when the exchange resumes.","weights":[2,2,4,2,2,1,1,1]},{"id":"baa2ff1e47f0","text":"Restore a stable position before taking another risk.","weights":[2,2,1,4,3,2,1,1]},{"id":"c2be0c93c079","text":"Help the person affected most recover before pushing the next step.","weights":[0,2,1,3,1,4,1,0]},{"id":"1927134f4600","text":"Notice which details changed and choose a measured adjustment.","weights":[1,3,2,1,1,0,4,0]},{"id":"8ebd89f5ed5d","text":"Push for a decisive step even if it leaves less room for recovery.","weights":[3,1,2,1,2,0,1,4]}],"pair":null},{"version":2,"id":"v2-teamfight","prompt":"A teammate is drawing pressure while you have room to act. What is your contribution?","category":"combat","options":[{"id":"265a5efaf341","text":"Commit alongside them so the pressure cannot stay one-sided.","weights":[4,1,2,4,1,1,1,2]},{"id":"112e8ca557d4","text":"Coordinate a sequence that makes both contributions count.","weights":[1,4,2,3,2,1,2,1]},{"id":"de023f384d25","text":"Give them a dependable way to recover and regroup.","weights":[3,2,1,4,2,2,1,1]},{"id":"a4447d2324ac","text":"Make the opposition look in the wrong direction at the right time.","weights":[1,3,2,1,4,1,1,1]},{"id":"1903ed746d44","text":"Keep enough distance to observe, then commit to a clear opening.","weights":[1,3,2,1,1,0,4,0]},{"id":"0834af27eca6","text":"Channel frustration into a bold commitment and accept the personal risk.","weights":[3,1,2,1,2,0,1,4]}],"pair":null},{"version":2,"id":"v2-finalexchange","prompt":"Only one meaningful exchange remains. What would you rather rely on?","category":"combat","options":[{"id":"c08e1465ea96","text":"A clear commitment that uses everything still available.","weights":[4,2,2,3,1,1,1,2]},{"id":"29ebf5aa0928","text":"A response built from the patterns you have verified.","weights":[1,4,2,2,2,1,2,1]},{"id":"4fe5be47da4a","text":"Your ability to adjust faster than the situation changes.","weights":[2,2,4,2,2,1,1,1]},{"id":"370c01d09551","text":"An expectation you have carefully encouraged them to believe.","weights":[1,4,2,1,4,1,1,1]},{"id":"62871a0110c0","text":"Make space for others to recover, then choose a dependable next step.","weights":[0,2,1,3,1,4,1,0]},{"id":"3d24c0e3f6e8","text":"Trade some safety for an immediate chance to change the situation.","weights":[3,1,2,1,2,0,1,4]}],"pair":null},{"version":2,"id":"v2-lost","prompt":"Your group is lost and everyone has a different idea. What do you do first?","category":"everyday","options":[{"id":"d0d01a39faf0","text":"Pick a workable direction and take responsibility for moving.","weights":[4,1,2,3,2,1,1,2]},{"id":"55e51bc38e43","text":"Compare what each person knows before choosing a route.","weights":[1,4,2,2,2,1,2,1]},{"id":"fd441bb90f0c","text":"Try a short route while keeping alternatives open.","weights":[2,2,4,2,2,1,1,1]},{"id":"08ba8b6ead0e","text":"Get everyone to a safe place before making the next decision.","weights":[2,2,1,4,3,2,1,1]},{"id":"63f2185fadd0","text":"Give both sides breathing room and help the quieter person recover confidence.","weights":[0,2,1,3,1,4,1,0]},{"id":"84ba07027883","text":"Watch one small detail closely and act when it becomes reliable.","weights":[1,3,2,1,1,0,4,0]}],"pair":null},{"version":2,"id":"v2-planfails","prompt":"A project plan falls apart just before a deadline. What comes naturally?","category":"everyday","options":[{"id":"b9b6ecc1a3be","text":"Identify the broken dependency and rebuild around it.","weights":[1,4,2,2,2,1,2,1]},{"id":"138bbb92ac2b","text":"Change the approach quickly using what is still available.","weights":[2,3,4,1,2,1,1,1]},{"id":"013b1d666449","text":"Protect the work already completed and limit further damage.","weights":[2,3,1,4,2,2,1,1]},{"id":"9c1de7d3a960","text":"Use the disruption to try an opening the original plan excluded.","weights":[1,3,2,1,4,1,1,1]},{"id":"3f4276a8cd35","text":"Set a small test that turns uncertainty into a clear signal.","weights":[1,3,2,1,1,0,4,0]},{"id":"6132867d2cfd","text":"Use the pressure as a reason to commit harder, while recognizing the cost.","weights":[3,1,2,1,2,0,1,4]}],"pair":null},{"version":2,"id":"v2-newgame","prompt":"Friends invite you into a game you do not understand yet. How do you begin?","category":"everyday","options":[{"id":"4c7449ed9509","text":"Try a clear move and learn from the response.","weights":[4,1,3,3,1,1,1,2]},{"id":"62033e9272d8","text":"Experiment with small changes as you learn.","weights":[2,2,4,1,2,1,1,1]},{"id":"beff383b5cfa","text":"Start with dependable choices until the risks become clear.","weights":[2,2,1,4,3,2,1,1]},{"id":"48234fcda0bc","text":"Look for assumptions everyone else is taking for granted.","weights":[1,3,2,1,4,1,1,1]},{"id":"eed8aa8e89af","text":"Spend some of your own margin to keep the whole group moving.","weights":[0,2,1,3,1,4,1,0]},{"id":"beb8f858a7e1","text":"Take a demanding route and accept the consequences of committing to it.","weights":[3,1,2,1,2,0,1,4]}],"pair":null},{"version":2,"id":"v2-disagreement","prompt":"Your group disagrees about what to do next. How do you help?","category":"everyday","options":[{"id":"38e7c9441a32","text":"State a clear position and take responsibility for its consequences.","weights":[4,1,2,4,1,1,1,2]},{"id":"101e941e4ee7","text":"Separate the disagreement into points that can be checked.","weights":[1,4,2,2,2,1,2,1]},{"id":"1fd84479e7a9","text":"Slow things down so nobody is pressured into a bad decision.","weights":[2,2,1,4,2,2,1,1]},{"id":"1e7f98e0bca5","text":"Reframe the choice so an overlooked option becomes possible.","weights":[2,3,2,1,4,1,1,1]},{"id":"eaece8bf66c8","text":"Help the person affected most recover before pushing the next step.","weights":[0,2,1,3,1,4,1,0]},{"id":"8a5d53236f8c","text":"Notice which details changed and choose a measured adjustment.","weights":[1,3,2,1,1,0,4,0]}],"pair":null},{"version":2,"id":"v2-deadline","prompt":"Several unexpected tasks arrive at once. What is your first instinct?","category":"everyday","options":[{"id":"389108cb4114","text":"Map the dependencies before dividing the time.","weights":[1,4,2,2,3,1,2,1]},{"id":"bc561b761935","text":"Start with something small and switch as priorities change.","weights":[2,2,4,2,2,1,1,1]},{"id":"db7d55a1a552","text":"Find a way to change the terms instead of accepting every demand.","weights":[1,4,2,1,4,1,1,1]},{"id":"0d8c16dbf8f1","text":"Rebuild trust and confidence so a setback does not spread.","weights":[0,2,1,3,1,4,1,0]},{"id":"122fd837e868","text":"Keep enough distance to observe, then commit to a clear opening.","weights":[1,3,2,1,1,0,4,0]},{"id":"c58ca4a9f6a6","text":"Channel frustration into a bold commitment and accept the personal risk.","weights":[3,1,2,1,2,0,1,4]}],"pair":null},{"version":2,"id":"v2-opportunity","prompt":"You receive an interesting offer with incomplete information. What do you do?","category":"everyday","options":[{"id":"f35caf91ffef","text":"Commit if the core purpose is clear and own the uncertainty.","weights":[4,2,2,3,1,1,1,2]},{"id":"f7f84d11dd78","text":"Try a limited version that allows a change of direction.","weights":[2,2,4,1,2,1,1,1]},{"id":"b1f6db296341","text":"Keep your dependable commitments intact while considering it.","weights":[2,3,1,4,2,2,1,1]},{"id":"4efb1bf0c064","text":"Make space for others to recover, then choose a dependable next step.","weights":[0,2,1,3,1,4,1,0]},{"id":"727e4c38af65","text":"Look for a narrow, dependable opportunity that others are overlooking.","weights":[1,3,2,1,1,0,4,0]},{"id":"a8903b7ba3bc","text":"Trade some safety for an immediate chance to change the situation.","weights":[3,1,2,1,2,0,1,4]}],"pair":null},{"version":2,"id":"v2-budget","prompt":"Your team has fewer resources than expected. What do you suggest?","category":"everyday","options":[{"id":"c02ae780a2e9","text":"Put the remaining resources behind one essential objective.","weights":[4,1,2,3,1,1,1,2]},{"id":"68280582fce9","text":"Redesign the sequence so each resource serves more than one step.","weights":[1,4,2,2,2,1,2,1]},{"id":"7b31f17c70d2","text":"Keep a reserve so one mistake cannot end the effort.","weights":[2,2,2,4,2,2,1,1]},{"id":"bec54a70aa8a","text":"Trade an unexpected advantage for something the team actually needs.","weights":[1,3,2,1,4,1,1,1]},{"id":"7d50597c7755","text":"Watch one small detail closely and act when it becomes reliable.","weights":[1,3,2,1,1,0,4,0]},{"id":"67e08e325c9a","text":"Accept a personal cost to force a decisive change in momentum.","weights":[3,1,2,1,2,0,1,4]}],"pair":null},{"version":2,"id":"v2-leadership","prompt":"A team is waiting for someone to take the next step. What role suits you?","category":"everyday","options":[{"id":"3337dd5dc5fa","text":"Make a clear commitment that others can build around.","weights":[4,1,2,4,1,1,1,2]},{"id":"97a7f7801d8b","text":"Connect the scattered information into a useful plan.","weights":[1,4,2,2,3,1,2,1]},{"id":"f2c98b8fa9d1","text":"Go where the team is struggling and adjust as needed.","weights":[2,3,4,1,2,1,1,1]},{"id":"65947999bb89","text":"Notice the opportunity that the usual roles have missed.","weights":[1,3,2,2,4,1,1,1]},{"id":"b1c8431346ee","text":"Check who is struggling most and help them regain a stable footing.","weights":[0,2,1,3,1,4,1,0]},{"id":"9d960a1cd0cc","text":"Use the pressure as a reason to commit harder, while recognizing the cost.","weights":[3,1,2,1,2,0,1,4]}],"pair":null},{"version":2,"id":"v2-incomplete","prompt":"You must solve a problem, but the explanation is incomplete. How do you proceed?","category":"everyday","options":[{"id":"b0c1d305db7e","text":"Tackle the part that is clear and build from the result.","weights":[4,1,2,4,1,1,1,2]},{"id":"c8ae3b7dd8be","text":"List what must be true and test the most important assumption.","weights":[1,4,2,2,2,1,2,1]},{"id":"54e26ad65bd1","text":"Try a small experiment and change direction based on feedback.","weights":[2,2,4,1,2,1,1,1]},{"id":"a733da72a81a","text":"Avoid irreversible steps until the situation is better understood.","weights":[2,2,2,4,2,2,1,1]},{"id":"83c14b54d6b7","text":"Spend some of your own margin to keep the whole group moving.","weights":[0,2,1,3,1,4,1,0]},{"id":"f8db4902a422","text":"Prepare one precise response instead of spreading effort everywhere.","weights":[1,3,2,1,1,0,4,0]}],"pair":null},{"version":2,"id":"v2-criticism","prompt":"Someone dismisses an idea you have worked hard on. What do you do next?","category":"everyday","options":[{"id":"8c3560ab1584","text":"Ask which assumption they disagree with and examine it.","weights":[1,4,2,2,3,1,2,1]},{"id":"c77bf5eed081","text":"Rework the approach without becoming attached to its old form.","weights":[2,3,4,1,2,1,1,1]},{"id":"8871d18f5512","text":"Stay composed and decide which feedback is worth acting on.","weights":[2,3,1,4,2,2,1,1]},{"id":"b9da33090e0f","text":"Find a different setting where the overlooked value becomes obvious.","weights":[1,4,2,1,4,1,1,1]},{"id":"7226dbf87aa2","text":"Notice which details changed and choose a measured adjustment.","weights":[1,3,2,1,1,0,4,0]},{"id":"b707d3b59cb6","text":"Push for a decisive step even if it leaves less room for recovery.","weights":[3,1,2,1,2,0,1,4]}],"pair":null},{"version":2,"id":"v2-groupchange","prompt":"Halfway through a shared activity, the conditions suddenly change. What do you do?","category":"everyday","options":[{"id":"8eebd72d3eb2","text":"Keep the main commitment moving despite the disruption.","weights":[4,1,3,3,1,1,1,2]},{"id":"63b16b4a925e","text":"Change roles or direction as the new situation demands.","weights":[2,2,4,1,3,1,1,1]},{"id":"91b1d07a894c","text":"Make sure the change does not leave anyone unsupported.","weights":[3,2,1,4,2,2,1,1]},{"id":"7c438d295219","text":"Use the unexpected change to create a new advantage.","weights":[1,4,2,1,4,1,1,1]},{"id":"4417cc86e24a","text":"Rebuild trust and confidence so a setback does not spread.","weights":[0,2,1,3,1,4,1,0]},{"id":"e2ee3608df59","text":"Channel frustration into a bold commitment and accept the personal risk.","weights":[3,1,2,1,2,0,1,4]}],"pair":null},{"version":2,"id":"v2-trust","prompt":"A friend asks you to help with something difficult. What promise feels most natural?","category":"everyday","options":[{"id":"4588f79cc8d9","text":"I will show up and keep working through the hard part.","weights":[4,1,2,4,1,1,1,2]},{"id":"991c4fbbb04b","text":"I will help you understand the problem and plan the steps.","weights":[1,4,2,3,2,1,2,1]},{"id":"3840275454b5","text":"I will help keep the pressure from overwhelming you.","weights":[2,3,1,4,2,2,1,1]},{"id":"f920466079a3","text":"I will help find an opening that others have overlooked.","weights":[2,3,2,1,4,1,1,1]},{"id":"c55b70506fee","text":"Make space for others to recover, then choose a dependable next step.","weights":[0,2,1,3,1,4,1,0]},{"id":"9de9263cf525","text":"Look for a narrow, dependable opportunity that others are overlooking.","weights":[1,3,2,1,1,0,4,0]}],"pair":null},{"version":2,"id":"v2-det-berserker-guardian-0","prompt":"You have one last opportunity to influence an uncertain outcome. What guides your next step?","category":"determinant","options":[{"id":"2b2f284209e7","text":"Accept a personal cost to force a decisive change in momentum.","weights":[3,1,2,1,2,0,1,4]},{"id":"c99ed9d8094f","text":"Let them repeat it while preparing a measured response.","weights":[2,2,1,4,2,2,1,1]},{"id":"f9d7ce11574a","text":"Make one small commitment, observe its cost, and reconsider before extending it.","weights":[2,1,1,2,2,1,1,2]}],"pair":["berserker","guardian"]},{"version":2,"id":"v2-det-berserker-guardian-1","prompt":"Your earlier approach is understood now. What comes naturally as you make your next commitment?","category":"determinant","options":[{"id":"226bacc3854f","text":"Accept a personal cost to force a decisive change in momentum.","weights":[3,1,2,1,2,0,1,4]},{"id":"a9d3b94a79a8","text":"Let them repeat it while preparing a measured response.","weights":[2,2,1,4,2,2,1,1]},{"id":"85ec729fd12d","text":"Make one small commitment, observe its cost, and reconsider before extending it.","weights":[2,1,1,2,2,1,1,2]}],"pair":["berserker","guardian"]},{"version":2,"id":"v2-det-berserker-healer-0","prompt":"You have one last opportunity to influence an uncertain outcome. What guides your next step?","category":"determinant","options":[{"id":"4f8a34026b23","text":"Accept a personal cost to force a decisive change in momentum.","weights":[3,1,2,1,2,0,1,4]},{"id":"96c0e85f75aa","text":"Give both sides breathing room and help the quieter person recover confidence.","weights":[0,2,1,3,1,4,1,0]},{"id":"98ec6792c903","text":"Make one small commitment, observe its cost, and reconsider before extending it.","weights":[1,1,1,2,1,2,1,2]}],"pair":["berserker","healer"]},{"version":2,"id":"v2-det-berserker-healer-1","prompt":"Your earlier approach is understood now. What comes naturally as you make your next commitment?","category":"determinant","options":[{"id":"9ce875abbaa3","text":"Accept a personal cost to force a decisive change in momentum.","weights":[3,1,2,1,2,0,1,4]},{"id":"bc395532cb8f","text":"Give both sides breathing room and help the quieter person recover confidence.","weights":[0,2,1,3,1,4,1,0]},{"id":"631cbad47c08","text":"Make one small commitment, observe its cost, and reconsider before extending it.","weights":[1,1,1,2,1,2,1,2]}],"pair":["berserker","healer"]},{"version":2,"id":"v2-det-berserker-ninja-0","prompt":"You have one last opportunity to infl