"You have one last opportunity to influence an uncertain outcome. What guides your next step?","category":"determinant","options":[{"id":"c1ead353fbc6","text":"Absorb a little more pressure and commit hard when the opening arrives.","weights":[4,1,2,3,1,1,1,2]},{"id":"09ed0c9921ca","text":"Test the pattern once more before building a reliable response.","weights":[1,4,2,3,2,1,2,1]},{"id":"1b1ceadede90","text":"Make one small commitment, observe its cost, and reconsider before extending it.","weights":[2,2,2,3,1,1,1,1]}],"pair":["warrior","wizard"]},{"version":2,"id":"v2-det-warrior-wizard-1","prompt":"Your earlier approach is understood now. What comes naturally as you make your next commitment?","category":"determinant","options":[{"id":"42b7ee0c6069","text":"Absorb a little more pressure and commit hard when the opening arrives.","weights":[4,1,2,3,1,1,1,2]},{"id":"d05585774ccd","text":"Test the pattern once more before building a reliable response.","weights":[1,4,2,3,2,1,2,1]},{"id":"eac4eafe6f95","text":"Make one small commitment, observe its cost, and reconsider before extending it.","weights":[2,2,2,3,1,1,1,1]}],"pair":["warrior","wizard"]}]$pool$::jsonb) q(version integer,id text,category text,prompt text,options jsonb,pair text[]);
create or replace function public.kaidra_awakening_begin() returns jsonb language plpgsql security definer set search_path='' as $$
declare s public.awakening_sessions;identity jsonb;questions jsonb;begin
 if auth.uid() is null or not exists(select 1 from public.profiles where id=auth.uid() and not coalesce(is_banned,false)) then raise exception 'An active Kaidra account is required';end if;
 perform pg_advisory_xact_lock(hashtextextended('kaidra:awakening:'||auth.uid()::text,0));
 identity:=public.kaidra_battle_identity(auth.uid());if identity is not null then return jsonb_build_object('identity',identity,'question',null);end if;
 select * into s from public.awakening_sessions where user_id=auth.uid();
 if s.id is null then
  select jsonb_agg(jsonb_build_object('id',id,'prompt',prompt,'category',category,'options',options) order by random()) into questions
  from ((select * from public.awakening_questions where version=2 and active and category='combat' order by random() limit 6)
  union all(select * from public.awakening_questions where version=2 and active and category='everyday' order by random() limit 6)) pool;
  -- Answer order is randomized once and then frozen with the session snapshot.
  select jsonb_agg(q||jsonb_build_object('options',(select jsonb_agg(o order by random()) from jsonb_array_elements(q->'options') o))) into questions from jsonb_array_elements(questions) q;
  if jsonb_array_length(questions)<>12 then raise exception 'Determination pool is not ready';end if;
  insert into public.awakening_sessions(user_id,questions,version) values(auth.uid(),questions,2) returning * into s;
 else update public.awakening_sessions set expires_at=now()+interval '7 days' where id=s.id returning * into s;end if;
 return public.kaidra_awakening_view(s.id);
end $$;
notify pgrst,'reload schema';
commit;
